#include <atomic>
#include <cstdint>
#include <iostream>
#include <optional>

class QuoteSeqLock {
public:
    void begin_write() {
        sequence_.fetch_add(1, std::memory_order_relaxed);
        std::atomic_thread_fence(std::memory_order_release);
    }
    void write(std::int64_t bid, std::int64_t ask) {
        bid_.store(bid, std::memory_order_relaxed);
        ask_.store(ask, std::memory_order_relaxed);
    }
    void end_write() { sequence_.fetch_add(1, std::memory_order_release); }

    std::optional<std::int64_t> try_spread() const {
        std::uint64_t before = sequence_.load(std::memory_order_acquire);
        if ((before & 1u) != 0) {
            return std::nullopt;
        }
        std::int64_t spread = ask_.load(std::memory_order_relaxed) -
                              bid_.load(std::memory_order_relaxed);
        std::atomic_thread_fence(std::memory_order_acquire);
        if (before != sequence_.load(std::memory_order_relaxed)) {
            return std::nullopt;
        }
        return spread;
    }

    std::uint64_t counter() const {
        return sequence_.load(std::memory_order_relaxed);
    }

private:
    std::atomic<std::uint64_t> sequence_{0};
    std::atomic<std::int64_t> bid_{0};
    std::atomic<std::int64_t> ask_{0};
};

const char* show(const std::optional<std::int64_t>& value) {
    return value ? "ok" : "retry";
}

int main() {
    QuoteSeqLock book;
    book.begin_write();
    book.write(100, 103);
    std::cout << book.counter() << ' ' << show(book.try_spread());
    book.end_write();
    std::cout << ' ' << book.counter() << ' ' << show(book.try_spread()) << ' '
              << *book.try_spread() << '\n';
}

#include <cstdint>
#include <iostream>

struct Node {
    int value;
    Node* next;
};

struct Tagged {
    static constexpr std::uint64_t address_mask =
        (std::uint64_t{1} << 48) - 1;
    static std::uint64_t pack(Node* pointer, std::uint16_t tag) {
        auto address = reinterpret_cast<std::uintptr_t>(pointer);
        return (std::uint64_t{tag} << 48) | (address & address_mask);
    }
    static Node* pointer(std::uint64_t packed) {
        return reinterpret_cast<Node*>(
            static_cast<std::uintptr_t>(packed & address_mask));
    }
    static std::uint16_t tag(std::uint64_t packed) {
        return static_cast<std::uint16_t>(packed >> 48);
    }
};

int main() {
    Node node{5, nullptr};
    std::uint16_t generation = 0xFFFF;

    std::uint64_t observed = Tagged::pack(&node, generation);
    std::uint64_t after_one = Tagged::pack(&node, generation + 1);
    std::uint64_t after_many = Tagged::pack(&node, generation + 1 + 0xFFFF);

    std::cout << std::boolalpha << (observed == after_one) << ' '
              << (observed == after_many) << ' ' << Tagged::tag(after_many)
              << ' ' << (Tagged::pointer(after_many) == &node) << ' '
              << Tagged::pointer(after_many)->value << '\n';
}

