    Node* candidate = head.load(std::memory_order_acquire);
    bool still_head = candidate == head.load(std::memory_order_acquire);

    // A reclaimer runs in the window: unlink, scan the slots, free.
    head.store(candidate->next, std::memory_order_release);
    if (hazard.load(std::memory_order_seq_cst) != candidate) {
        delete candidate;
