#include <atomic>
#include <iostream>
#include <thread>

struct Node {
    int value;
    Node* next;
};

Node sentinel{1, nullptr};

// "Only the owning thread ever writes its own slot, so a plain pointer
// is fine here - we don't need the cost of an atomic store."
Node* hazard_slot = nullptr;
std::atomic<int> protections_seen{0};

int main() {
    std::thread reader{[] {
        for (int i = 0; i < 200'000; ++i) {
            hazard_slot = &sentinel;  // publish
            hazard_slot = nullptr;    // clear
        }
    }};
    std::thread reclaimer{[] {
        int seen = 0;
        for (int i = 0; i < 200'000; ++i) {
            if (hazard_slot == &sentinel) {  // scan every slot
                ++seen;
            }
        }
        protections_seen.store(seen, std::memory_order_relaxed);
    }};
    reader.join();
    reclaimer.join();
    std::cout << "scan complete\n";
}

