#include <atomic>

class SpinLock {
public:
    SpinLock() = default;
    SpinLock(const SpinLock&) = delete;             // a copied lock
    SpinLock& operator=(const SpinLock&) = delete;  // protects nothing

    // Bounded: reports failure instead of spinning forever, so the caller
    // can back off, queue the work, or take a slower path.
    bool try_lock_for(unsigned attempts) {
        for (unsigned i = 0; i < attempts; ++i) {
            // TEST first, with a plain load. A bare test_and_set loop
            // performs a read-modify-write on every iteration, and every
            // RMW must take exclusive ownership of the cache line - so N
            // spinners keep the line migrating between cores even though
            // none of them can win while the lock is held. A relaxed load
            // is satisfied by a shared copy and generates no traffic.
            if (!held_.test(std::memory_order_relaxed)) {
                // Only now pay for the RMW. acquire: everything in the
                // critical section stays after this.
                if (!held_.test_and_set(std::memory_order_acquire)) {
                    return true;
                }
            }
        }
        return false;
    }

    void unlock() {
        // release: everything in the critical section stays before this.
        held_.clear(std::memory_order_release);
    }

private:
    std::atomic_flag held_{};
};

class SpinGuard {
public:
    explicit SpinGuard(SpinLock& lock) : lock_(lock) {}
    ~SpinGuard() { if (held_) lock_.unlock(); }
    SpinGuard(const SpinGuard&) = delete;
    SpinGuard& operator=(const SpinGuard&) = delete;

    bool try_acquire(unsigned attempts) {
        held_ = lock_.try_lock_for(attempts);
        return held_;
    }

private:
    SpinLock& lock_;
    bool held_ = false;
};

// WHY THE BOUND CHANGES NOTHING ON THE LADDER. The progress question is
// about the OPERATION the lock protects, not about this function
// returning. There is still a holder: if the thread inside the critical
// section is descheduled, page-faults, or suffers priority inversion,
// every other thread is stopped - which is the definition of blocking.
// try_lock_for turns "wait forever" into "fail fast", which is an
// engineering improvement and not a progress guarantee: nobody completes
// the protected operation while the holder is stalled.

#include <atomic>

class ConnectionPool {
public:
    explicit ConnectionPool(int size) : free_(size) {}

    bool try_acquire() {
        int observed = free_.load(std::memory_order_relaxed);
        for (;;) {
            if (observed == 0) {
                // FAILURE LINEARIZATION POINT: the load that produced
                // `observed` - either the one above or the write-back of
                // the last failed CAS. The pool really was empty at that
                // instant. It may be non-empty by the time this returns,
                // which linearizability permits: the answer must have been
                // true at ONE point inside the call, not afterwards.
                return false;
            }
            // SUCCESS LINEARIZATION POINT: the successful CAS. Before it
            // the permit is not ours and the pool is unchanged; after it,
            // it is ours and no other caller can take the same one. The
            // decision and the mutation are the same indivisible event,
            // which is precisely what the original code lacked.
            //
            // weak: the loop retries anyway. success acquire: the permit
            // carries ownership of whatever the releasing thread last did
            // with the connection. failure relaxed: the observed value is
            // only compared and arithmetic - it reaches no other memory.
            if (free_.compare_exchange_weak(observed, observed - 1,
                                            std::memory_order_acquire,
                                            std::memory_order_relaxed)) {
                return true;
            }
            // No reload: the failed CAS already refreshed `observed`.
        }
    }

    void release() { free_.fetch_add(1, std::memory_order_release); }

    // Advisory only: stale the instant it returns. Never branch on it.
    int free_count() const { return free_.load(std::memory_order_relaxed); }

private:
    std::atomic<int> free_;
};

// WHY NO MEMORY ORDER COULD FIX THE ORIGINAL. Linearizability composes at
// the OBJECT-OPERATION level: free_count() and take() can each be
// perfectly linearizable while the client-side pair is not atomic. Two
// callers both observe 1 and both take, and every individual operation is
// still explicable by some legal sequential history - there is simply no
// history in which the pair is one step. Raising everything to seq_cst
// orders the operations more strictly and leaves that interleaving
// exactly as legal, because the defect is a missing OPERATION BOUNDARY,
// not a missing ordering edge. The alternatives are this compound
// operation or a lock held across the pair.

#include <algorithm>
#include <atomic>
#include <cstdint>
#include <thread>

class TokenBucket {
public:
    explicit TokenBucket(std::uint64_t tokens) : tokens_(tokens) {}

    bool try_consume(std::uint64_t cost) {
        std::uint64_t observed = tokens_.load(std::memory_order_relaxed);
        for (unsigned failures = 0;; ++failures) {
            // (1) The balance is checked against the value this attempt
            // will compare-and-exchange against, so the subtraction can
            // never be applied to a smaller balance than the one tested.
            if (observed < cost) {
                return false;
            }
            // weak: this loop retries anyway, so a spurious failure costs
            // one iteration and avoids the nested retry a strong CAS may
            // perform on an LL/SC machine.
            //
            // The desired value is recomputed from `observed` on every
            // attempt. A failed CAS already wrote the freshly observed
            // balance there; reloading explicitly would be wasted work and
            // would discard the exact value the CAS saw.
            if (tokens_.compare_exchange_weak(observed, observed - cost,
                                              std::memory_order_acquire,
                                              std::memory_order_relaxed)) {
                return true;
            }
            backoff(failures);
        }
    }

    // (2) fetch_add is a read-modify-write: it reads the modification
    // immediately preceding it in this object's modification order, so a
    // refill landing in the middle of a consumer's retry loop cannot be
    // overwritten. A load/store refill WOULD lose it - that is the whole
    // reason the refill is not "tokens_.store(load() + n)".
    void refill(std::uint64_t tokens) {
        tokens_.fetch_add(tokens, std::memory_order_release);
    }

private:
    static void backoff(unsigned failures) {
        unsigned shift = std::min(failures, 8u);  // cap the doubling
        unsigned spins = 1u << shift;
        for (unsigned i = 0; i < spins; ++i) {
            // Keeps the empty spin from being optimised away. This is a
            // COMPILER barrier, not a processor pause instruction -
            // production wraps a target-specific pause behind a shim.
            std::atomic_signal_fence(std::memory_order_seq_cst);
        }
        if (failures > 8) {
            std::this_thread::yield();  // escalate to the scheduler
        }
    }

    std::atomic<std::uint64_t> tokens_;
};

// (3) WHAT BACKOFF BUYS: fewer exclusive-ownership requests per unit time,
// so the cache line carrying `tokens_` migrates less and the group makes
// more aggregate progress. It can also improve observed fairness.
//
// WHAT IT DOES NOT BUY: this loop is still only lock-free. CAS fairness is
// not guaranteed - one core can keep winning while another keeps
// refreshing `observed` - so a particular caller can starve without the
// progress guarantee being violated, and no delay tuning promotes the
// algorithm to wait-free. Constants tuned on one processor, core count or
// scheduler are not universal.

#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <optional>

class DepthSeqLock {
public:
    static constexpr std::size_t levels = 4;
    using Ladder = std::array<std::int64_t, levels>;

    // SINGLE WRITER ONLY. Two writers would interleave their odd/even
    // transitions and a reader could bracket a mixed generation; that
    // needs a separate writer-serialization mechanism.
    void store(const Ladder& prices) {
        sequence_.fetch_add(1, std::memory_order_relaxed);   // -> odd
        std::atomic_thread_fence(std::memory_order_release);
        for (std::size_t i = 0; i < levels; ++i) {
            prices_[i].store(prices[i], std::memory_order_relaxed);
        }
        sequence_.fetch_add(1, std::memory_order_release);   // -> even
    }

    // (3) BOUNDED. A writer that dies between its two increments leaves
    // the counter odd forever, and an unbounded retry loop would then spin
    // for the life of the process. Reporting failure lets the caller
    // escalate - the reader is the one component that must not be taken
    // down by the writer's fault.
    std::optional<Ladder> try_load(unsigned attempts) const {
        for (unsigned i = 0; i < attempts; ++i) {
            std::uint64_t before = sequence_.load(std::memory_order_acquire);
            if ((before & 1u) != 0) {
                continue;  // a write is in progress
            }

            Ladder snapshot{};
            for (std::size_t level = 0; level < levels; ++level) {
                snapshot[level] =
                    prices_[level].load(std::memory_order_relaxed);
            }

            std::atomic_thread_fence(std::memory_order_acquire);
            if (before == sequence_.load(std::memory_order_relaxed)) {
                return snapshot;  // equal EVEN counters bracket the reads
            }
        }
        return std::nullopt;
    }

private:
    // (2) Payload fields are ATOMIC. Plain fields would race with the
    // writer, and discarding a torn snapshot afterwards does not repair
    // undefined behaviour - UB is a property of the execution, not of the
    // value you keep.
    std::atomic<std::uint64_t> sequence_{0};
    std::array<std::atomic<std::int64_t>, levels> prices_{};
};

// THE PROOF, BOTH DIRECTIONS:
//  (a) If the reader observes a COMPLETED even generation, the writer's
//      final release increment published every payload store before it, so
//      the relaxed loads observe that generation or something later.
//  (b) If the reader observes any field from an IN-PROGRESS generation,
//      the writer's odd increment is sequenced before its release fence,
//      so the reader's acquire fence forces its final sequence load to
//      observe the odd value or later - and the equality check fails.
//  Equal even counters therefore bracket a payload from one generation.
//
// WHAT GROWING THE PAYLOAD COSTS: the reader's payload loads are the
// overlap window. Four levels is a handful of loads; forty would widen the
// window enough that a write burst turns into a retry storm, and with a
// bounded try_load that shows up as failed reads rather than as latency.
// Keep the payload small and trivially copyable, or publish an immutable
// snapshot by pointer instead.

#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <optional>

class IndexStack {
public:
    static constexpr std::uint32_t capacity = 1024;
    static constexpr std::uint32_t none = 0xFFFF'FFFFu;

    // {generation, index} in one 64-bit word. No address bits are stolen,
    // so nothing here depends on a 48-bit virtual-address convention,
    // five-level paging, or hardware pointer tags. The generation gets a
    // full 32 bits instead of 16, which pushes the wrap bound far out of
    // reach of any realistic outstanding observation.
    static constexpr std::uint64_t pack(std::uint32_t generation,
                                        std::uint32_t index) {
        return (std::uint64_t{generation} << 32) | index;
    }
    static constexpr std::uint32_t index_of(std::uint64_t packed) {
        return static_cast<std::uint32_t>(packed);
    }
    static constexpr std::uint32_t generation_of(std::uint64_t packed) {
        return static_cast<std::uint32_t>(packed >> 32);
    }

    bool push(std::uint32_t slot, int value) {
        if (slot >= capacity) {
            return false;  // capacity is an explicit system limit
        }
        values_[slot].store(value, std::memory_order_relaxed);

        std::uint64_t observed = head_.load(std::memory_order_relaxed);
        for (;;) {
            next_[slot].store(index_of(observed), std::memory_order_relaxed);
            // Every mutation bumps the generation, so a stalled thread's
            // saved word can never match again.
            std::uint64_t desired = pack(generation_of(observed) + 1, slot);
            if (head_.compare_exchange_weak(observed, desired,
                                            std::memory_order_release,
                                            std::memory_order_relaxed)) {
                return true;
            }
            // Failure refreshed `observed`; the link is rewritten from it.
        }
    }

    std::optional<int> pop() {
        std::uint64_t observed = head_.load(std::memory_order_acquire);
        for (;;) {
            std::uint32_t slot = index_of(observed);
            if (slot == none) {
                return std::nullopt;
            }
            // (3) This read is SPECULATIVE - the slot may already have been
            // popped and re-pushed by another thread. It is safe on both
            // counts: the slot's storage lives for the process, so there is
            // no use-after-free, and `next_` is atomic, so a concurrent
            // push writing the same element is not a data race. A stale
            // value can only make the CAS below fail, because the
            // generation moved.
            std::uint32_t next = next_[slot].load(std::memory_order_relaxed);
            std::uint64_t desired = pack(generation_of(observed) + 1, next);
            if (head_.compare_exchange_weak(observed, desired,
                                            std::memory_order_acq_rel,
                                            std::memory_order_acquire)) {
                return values_[slot].load(std::memory_order_relaxed);
            }
        }
    }

private:
    std::array<std::atomic<int>, capacity> values_{};
    std::array<std::atomic<std::uint32_t>, capacity> next_{};
    alignas(64) std::atomic<std::uint64_t> head_{pack(0, none)};
};

static_assert(std::atomic<std::uint64_t>::is_always_lock_free,
              "the head word must not fall back to a library lock");

// WHAT THIS REMOVES: (a) pointer ABA, because identity is an index plus a
// generation rather than an address the allocator may hand back; and (b)
// safe memory reclamation entirely - no hazard pointers, no epochs, no
// retired lists, because nothing is ever freed and every speculative read
// targets storage that outlives the process's use of it.
//
// THE NEW LIMIT: capacity is fixed at construction and exhaustion is a
// visible, explicit failure rather than a call to the allocator. Slot
// ownership also becomes the caller's problem - pushing a slot that is
// already on the stack corrupts the chain, which is the price of naming
// nodes instead of allocating them.

