#include <atomic>
#include <optional>

struct Node {
    int value;
    Node* next;
};

extern std::atomic<Node*> head;

class HazardSlot {
public:
    void publish(Node* node) {
        protected_.store(node, std::memory_order_seq_cst);
    }
    void clear() { protected_.store(nullptr, std::memory_order_seq_cst); }
    Node* get() const { return protected_.load(std::memory_order_seq_cst); }

private:
    std::atomic<Node*> protected_{nullptr};
};

std::optional<int> read_head(HazardSlot& hazard) {
    for (;;) {
        Node* node = head.load(std::memory_order_acquire);

        // DEFECT 1 - the original validated first and published second.
        // WINDOW: between the re-read and the publish, another thread can
        // unlink the node, scan every hazard slot (finding this one still
        // empty) and free it. The reader then dereferences freed memory,
        // having "validated" a fact that expired the instant it was
        // established. Publishing first is what makes the validation
        // meaningful.
        hazard.publish(node);

        // Now validate. If head still names the node, the publication was
        // already established at a point where the node was still linked,
        // so any scan performed afterwards must observe it.
        if (node != head.load(std::memory_order_acquire)) {
            continue;  // republish the new candidate on the next lap
        }

        if (node == nullptr) {
            // DEFECT 2 - the original returned here with the slot still
            // published. WINDOW: none for this node, but the slot now
            // permanently names a stale pointer, so every future scan
            // retains whatever node happens to sit at that address and the
            // retired list grows without bound. Clearing is what makes the
            // memory bound real.
            hazard.clear();
            return std::nullopt;
        }

        int value = node->value;  // protected dereference

        // DEFECT 3 - the original returned with the slot published on the
        // success path too, with the same unbounded-retention effect.
        hazard.clear();
        return value;
    }
}

// THE RECLAIMER SIDE, which is what makes the above sound: unlinked nodes
// go onto a per-thread RETIRED list, and periodically the owner scans
// EVERY hazard slot and frees only those retired nodes that no slot names;
// nodes still named are kept for the next scan. That is also why clearing
// this thread's own slot is safe even though the node may be about to be
// retired - another thread's slot may still protect it, and the scan
// honours that.

#include <charconv>
#include <cstddef>
#include <expected>
#include <optional>
#include <span>
#include <string_view>
#include <variant>

struct Trade { int price; int quantity; };
struct Quote { int price; int quantity; };

using Message = std::variant<Trade, Quote>;

enum class ParseError { EmptyPacket, UnknownKind, BadField, TrailingData };

// The packet is borrowed, never copied: a span in, a value out.
std::expected<Message, ParseError> decode(std::span<const char> packet) {
    std::string_view text{packet.data(), packet.size()};
    if (text.empty()) return std::unexpected(ParseError::EmptyPacket);

    const char kind = text.front();
    if (kind != 'T' && kind != 'Q') return std::unexpected(ParseError::UnknownKind);

    int fields[2]{};
    std::size_t at = 1;
    for (int& field : fields) {
        if (at >= text.size() || text[at] != '|') return std::unexpected(ParseError::BadField);
        ++at;
        const auto* first = text.data() + at;
        const auto* last = text.data() + text.size();
        const auto result = std::from_chars(first, last, field);
        if (result.ec != std::errc{}) return std::unexpected(ParseError::BadField);
        at = static_cast<std::size_t>(result.ptr - text.data());
    }
    if (at != text.size()) return std::unexpected(ParseError::TrailingData);

    if (kind == 'T') return Message{Trade{fields[0], fields[1]}};
    return Message{Quote{fields[0], fields[1]}};
}

enum class Ingest { Accepted, Malformed, Dropped };

// A queue whose push reports refusal rather than blocking or growing.
template <class Queue>
Ingest ingest(Queue& queue, std::span<const char> packet) {
    const auto decoded = decode(packet);
    if (!decoded) return Ingest::Malformed;          // bad input
    if (!queue.try_push(*decoded)) return Ingest::Dropped;  // overload
    return Ingest::Accepted;
}

#include <atomic>
#include <cstdint>

// A bounded SPSC ring; only the consumer calls pop().
class MessageRing {
public:
    bool pop(int& value) noexcept;
};

std::atomic<bool> stopping{false};

// Called by the control thread. Release: everything this thread did before
// requesting the stop - including every push - is published to whoever
// observes the flag.
void stop() {
    stopping.store(true, std::memory_order_release);
}

std::uint64_t drain(MessageRing& ring) {
    std::uint64_t consumed = 0;
    int value = 0;

    for (;;) {
        if (ring.pop(value)) {
            ++consumed;
            continue;  // never look at the flag while there is work
        }

        // Empty. ONLY NOW consult the stop flag. Acquire pairs with the
        // release in stop(), so observing `true` also makes visible every
        // push the stopping thread had already published.
        if (stopping.load(std::memory_order_acquire)) {
            // Drain once more before leaving: a producer may have pushed
            // between our failed pop and this load, and contract (2) says
            // that item must not be stranded.
            while (ring.pop(value)) {
                ++consumed;
            }
            return consumed;
        }
        // Otherwise keep polling (a real consumer would pause or block
        // here rather than burn the core).
    }
}

// WHY THE ORDER OF THE CHECKS IS THE ARGUMENT. Inverting them -
//     while (!stopping.load(acquire)) { if (ring.pop(v)) ...; }
// - is the classic lost-tail bug: the flag is observed true while items
// remain queued, and the loop exits with the queue non-empty. Checking the
// QUEUE first and the FLAG only on empty gives the invariant that matters:
// the flag is consulted at a moment when the consumer has just seen the
// queue empty, and any push that raced that observation is caught by the
// final drain. Because the producer performs no push after stop() returns,
// that second drain is the last one needed.
//
// CONTRACT (1) needs no extra mechanism: starting a thread synchronizes
// with the beginning of its function, so a consumer created after stop()
// already observes both the flag and every earlier push, and exits on its
// first empty pop.
